SELECT * FROM invocation
WHERE task_id = #{taskId}
ORDER BY created_at ASC, invocation_id ASC

SELECT * FROM invocation
WHERE task_id = #{taskId} AND user_id = #{userId}
ORDER BY created_at ASC, invocation_id ASC

SELECT * FROM invocation
WHERE trace_id = #{traceId} AND user_id = #{userId}
ORDER BY created_at ASC, invocation_id ASC

SELECT * FROM invocation
WHERE agent_id = #{agentId} AND status = #{status}
ORDER BY created_at ASC, invocation_id ASC

SELECT * FROM invocation
WHERE agent_id = #{agentId} AND user_id = #{userId} AND status = #{status}
ORDER BY created_at ASC, invocation_id ASC
